import math  
def next_Perfect_Square(N): 
    if N < 0:
        return 0
    nextN = math.floor(math.sqrt(N)) + 1
    return nextN * nextN

def sum_series(n):
  if n <= 0:
    return 0
  return sum(n - 2 * i for i in range(n // 2 + 1))

