            comp = k ^ val
            if comp in cnt[x][y]:
                res[0] += cnt[x][y][comp]
            return

        val ^= g[x][y]

        if x > 0:
            go_end(x-1, y, val, steps + 1)
        if y > 0:
            go_end(x, y-1, val, steps + 1)

    go_start(0, 0, 0, 0)
    go_end(n-1, m-1, 0, 0)

