    if len(s) > 1 and s[-2:] == c1 + c2:
        return 0

    if len(s) > 1 and s[-2:] == c2 + c1:
        return 1

    i2 = find_right(s, c2)
    if i2 == inf:
        return inf

    i1 = find_right(s, c1, i2)
    if i1 == inf:
        return inf

    ans = 0
