            return a
        else:
            self.vs[a] = b
            self.sizes[b] += self.sizes[a]
            self.states[b] = mergedState
            return b

    def flatten(self):
        for i in range(len(self.vs)):
            self.get(i)

    def setNames(self):
        self.flatten()
        return set(self.vs)

