        low[u] = dfs.dfs_time
        disc[u] = dfs.dfs_time
        in_stack[u] = True
        st.append(u)

        for v in adj[u]:
            if disc[v] == -1:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif in_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            comp.append([])
            while u != st[-1]:
                x = st.pop()
                in_stack[x] = False
                comp[-1].append(x)
            x = st.pop()
            in_stack[x] = False
            comp[-1].append(x)

    dfs.dfs_time = 0
    for i in range(1, n + 1):
        if disc[i] == -1:
            dfs(i)

    return comp[::-1]

