def calc(am, con):
    ans = am
    for i in range(len(con)):
        if am % 2 != 0:
            if con[i] >= am and i != 0:
                ans += am
            return ans
        if i == 0:
            am //=2
            continue
        if con[i] >= am:
            ans += am
            am //=2
        else:
            return ans
    return ans


