import sys


def get(v):
	if v == prev[v]:
		return v
	prev[v] = get(prev[v])
	return prev[v]

def join(u, v):
	u = get(u); v = get(v)
	if u != v:
		if size[u] < size[v]:
			u, v = v, u
		prev[v] = u
		size[u] += size[v]


