        if umbrellas[x] == -1 or w[umbrellas[x]] > w[i]:
            umbrellas[x] = i

    dp = [[math.inf for _ in range(m+1)] for _ in range(a+1)]
    dp[0][m] = 0
    for i in range(a):
        for j in range(m+1):
            if dp[i][j] == math.inf:
                continue
            if not raining[i]:
                dp[i+1][m] = min(dp[i+1][m], dp[i][j])
